mapper.select:
/* 답변 단건 조회 (PK 기준) */
 SELECT *
 FROM inquiry_answer
 WHERE answer_id = #{qnaAnswerId}

mapper.update:
/* 답변 수정 */
 UPDATE inquiry_answer
 SET answer_content = #{content},
     updated_at = NOW()
 WHERE answer_id = #{qnaAnswerId}

/* 답변 논리적 삭제 */
UPDATE inquiry_answer
SET deleted_yn = 'Y',
    updated_at = NOW()
WHERE answer_id = #{qnaAnswerId}

/* 문의글 상태 변경 (답변대기 | 답변완료) */
UPDATE inquiry
SET answer_status = #{status}
WHERE inquiry_id = #{qnaId}
